// Contrôler le dépôt avant tout travail : type et taille du fichier, ou adresse du lien. Rien ne part vers un modèle ici.
// Entrée : { origine: 'fichier' | 'lien', nom, taille, url }, ou un fichier joint. Sortie : { ok, motif, origine, cle, titre, source, lecture_prevue, binaire, texte }.
const recu = $input.first(), e0 = recu.json || {}, bin = recu.binary || {}, cleBin = Object.keys(bin)[0] || null;
const e = Object.assign({}, e0.body && typeof e0.body === 'object' && !Array.isArray(e0.body) ? e0.body : e0);
// Un fichier joint par le portail : son nom et son poids viennent du fichier lui-même.
const poids = t => { const m = String(t || '').match(/([\d.,]+)\s*(B|kB|MB|GB)/i); return m ? parseFloat(m[1].replace(',', '.')) * ({ b: 1, kb: 1024, mb: 1048576, gb: 1073741824 })[m[2].toLowerCase()] : 0; };
if (cleBin) { e.origine = 'fichier'; e.nom = bin[cleBin].fileName || e.nom; e.taille = poids(bin[cleBin].fileSize) || e.taille || 1; }
if (e.origine === 'fichier' && typeof e.texte === 'string' && !cleBin) e.taille = e.texte.length;
const TYPES = { pdf: 'pdf', txt: 'texte', md: 'texte', html: 'page', htm: 'page' };
const TAILLE_MAX = 15 * 1024 * 1024;
const refus = motif => [{ json: { ok: false, motif: motif } }];
const accepte = j => [{ json: Object.assign({ ok: true, binaire: cleBin, texte: !cleBin && typeof e.texte === 'string' ? e.texte : null }, j), binary: bin }];
if (e.origine === 'fichier') {
  const nom = String(e.nom || '').trim().slice(0, 200);
  const ext = (nom.match(/\.([a-z0-9]{1,5})$/i) || [])[1];
  if (!nom) return refus('Le fichier n\'a pas de nom.');
  if (ext && ext.toLowerCase() === 'docx') return refus('Word n\'est pas encore pris en charge : enregistrez le document en PDF, puis déposez-le.');
  if (!ext || !TYPES[ext.toLowerCase()]) return refus('Type de fichier non pris en charge. Types acceptés : PDF, texte, page HTML.');
  if (!(Number(e.taille) > 0)) return refus('Le fichier est vide.');
  if (Number(e.taille) > TAILLE_MAX) return refus('Fichier trop lourd : 15 Mo au plus.');
  const titre = nom.replace(/\.[a-z0-9]{1,5}$/i, '').replace(/[_-]+/g, ' ').replace(/\s+/g, ' ').trim();
  return accepte({ origine: 'fichier', cle: 'fichier:' + nom.toLowerCase().replace(/\s+/g, ' '), titre: titre.charAt(0).toUpperCase() + titre.slice(1), source: nom, lecture_prevue: TYPES[ext.toLowerCase()] });
}
if (e.origine === 'lien') {
  const brut = String(e.url || '').trim();
  if (!brut || brut.length > 2000) return refus('Adresse absente ou trop longue.');
  // L'adresse est découpée à la main : l'objet URL n'existe pas dans un nœud Code de n8n.
  if (/\s/.test(brut)) return refus('Adresse illisible.');
  let adresse = brut;
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(adresse)) { if (/^[a-z][a-z0-9+-]*:/i.test(adresse)) return refus('Seules les adresses http et https sont acceptées.'); adresse = 'https://' + adresse; }
  const m = adresse.match(/^([a-z][a-z0-9+.-]*):\/\/(?:([^\/?#@]*)@)?(\[[^\]]*\]|[^\/?#:]*)(?::(\d*))?([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i);
  if (!m) return refus('Adresse illisible.');
  const protocole = m[1].toLowerCase(), port = m[4] || '';
  if (protocole !== 'https' && protocole !== 'http') return refus('Seules les adresses http et https sont acceptées.');
  if (m[2] !== undefined) return refus('Une adresse ne doit pas contenir d\'identifiants.');
  const h = m[3].toLowerCase().replace(/\.$/, '');
  // Jamais d'adresse interne : ni machine locale, ni réseau privé, ni adresse chiffrée.
  const interne = !h || h === 'localhost' || /\.(local|localhost|internal|lan|home|corp|test)$/.test(h) || !h.includes('.') || /^[0-9.]+$/.test(h) || /^0x/i.test(h) || /[:\[\]%\\]/.test(h) || !/^[a-z0-9.-]+$/.test(h);
  if (interne) return refus('Cette adresse désigne une machine interne ou une adresse chiffrée. Donnez l\'adresse publique de la page.');
  if (port && port !== '80' && port !== '443') return refus('Port non autorisé.');
  const params = (m[6] || '').split('&').filter(Boolean).map(x => { const k = x.indexOf('='); return k < 0 ? [x, ''] : [x.slice(0, k), x.slice(k + 1)]; }).filter(([k]) => !/^(utm_|fbclid|gclid|mc_|ref$)/i.test(k)).sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0);
  const chemin = (m[5] || '').replace(/\/+$/, '');
  const requete = params.length ? '?' + params.map(([k, v]) => k + '=' + v).join('&') : '';
  const propre = 'https://' + h + chemin + requete;
  const pdf = /\.pdf$/i.test(chemin);
  return accepte({ origine: 'lien', cle: 'lien:' + h.replace(/^www\./, '') + chemin + requete, titre: h.replace(/^www\./, '') + chemin, source: propre, lecture_prevue: pdf ? 'pdf' : 'page' });
}
return refus('Dépôt inconnu : il faut un fichier ou un lien.');

// Numéroter : retrouver dans le registre la version en service de ce document, et donner son numéro à la nouvelle.
const recu = $('Contrôler le dépôt').first(), d = recu.json;
const lignes = $input.all().map(i => i.json).filter(l => l && l.doc_id);
const actuelle = lignes.find(l => l.statut === 'en_service') || null;
const version = lignes.reduce((m, l) => Math.max(m, Number(l.version) || 0), 0) + 1;
// La voie de lecture : texte fourni par un essai, page web, PDF en ligne, PDF déposé, fichier texte déposé.
const voie = d.texte ? 'direct' : d.origine === 'lien' ? (d.lecture_prevue === 'pdf' ? 'pdf_lien' : 'page') : d.lecture_prevue === 'pdf' ? 'pdf_fichier' : d.lecture_prevue === 'page' ? 'page_fichier' : 'texte_fichier';
return [{ json: { doc_id: 'doc-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8), version: version, voie: voie,
  ancien: actuelle ? { doc_id: actuelle.doc_id, version: Number(actuelle.version), empreinte: actuelle.empreinte } : null,
  origine: d.origine, cle: d.cle, titre: d.titre, source: d.source, binaire: d.binaire, texte: d.texte }, binary: recu.binary }];

// Nettoyer une page web capturée : on garde le texte utile et ses titres, on retire menus, pieds de page, scripts et formulaires.
// Entrée : { html }. Sortie : { titre, texte, nb_caracteres }. Les titres deviennent des lignes « # », lues ensuite par le découpage.
const e = $input.first().json;
let h = String(e.html || e.data || '').replace(/<!--[\s\S]*?-->/g, ' ');
const sansBalise = s => s.replace(/<[^>]+>/g, ' ');
const NOMS = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", rsquo: '’', lsquo: '‘', laquo: '«', raquo: '»', hellip: '…', ndash: '-', mdash: '-', euro: '€', deg: '°', eacute: 'é', egrave: 'è', ecirc: 'ê', euml: 'ë', agrave: 'à', acirc: 'â', ccedil: 'ç', ugrave: 'ù', ucirc: 'û', ocirc: 'ô', icirc: 'î', iuml: 'ï', oelig: 'œ', Eacute: 'É', Agrave: 'À', Ccedil: 'Ç' };
const decoder = s => s.replace(/&#x([0-9a-f]{1,6});/gi, (m, c) => String.fromCodePoint(parseInt(c, 16))).replace(/&#(\d{1,7});/g, (m, c) => String.fromCodePoint(+c)).replace(/&([a-zA-Z]{2,8});/g, (m, n) => n in NOMS ? NOMS[n] : m);
const titre = decoder(sansBalise((h.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i) || h.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i) || ['', ''])[1])).replace(/\s+/g, ' ').trim().slice(0, 200);
const INUTILE = 'script|style|noscript|svg|iframe|nav|aside|form|button|template|select|dialog';
const retirer = (s, noms) => s.replace(new RegExp('<(' + noms + ')\\b[\\s\\S]*?<\\/\\1>', 'gi'), ' ');
h = retirer(h, INUTILE);
// Texte caché dans la page (élément masqué, taille nulle, transparent) : un lecteur ne le voit pas, l'IA non plus.
const CACHE = /<([a-z][a-z0-9]*)\b(?=[^>]*(?:\shidden(?=[\s>=])|aria-hidden\s*=\s*["']?true|style\s*=\s*["'][^"']*(?:display\s*:\s*none|visibility\s*:\s*hidden|font-size\s*:\s*0(?![.\d])|opacity\s*:\s*0(?![.\d]))))[^>]*>[\s\S]*?<\/\1>/gi;
const nb_caches = (h.match(CACHE) || []).length;
h = h.replace(CACHE, ' ');
// Le corps utile : la zone principale de la page si elle existe et pèse assez, sinon toute la page sans en-tête ni pied.
const zone = (h.match(/<main\b[\s\S]*<\/main>/i) || h.match(/<article\b[\s\S]*<\/article>/i) || [])[0];
if (zone && sansBalise(zone).replace(/\s+/g, ' ').trim().length > 400) h = zone;
else h = retirer((h.match(/<body\b[\s\S]*<\/body>/i) || [h])[0], 'header|footer');
h = h.replace(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi, (m, n, t) => '\n\n' + '#'.repeat(+n) + ' ' + sansBalise(t).replace(/\s+/g, ' ').trim() + '\n\n')
  .replace(/<li\b[^>]*>/gi, '\n- ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(td|th)>/gi, ' | ')
  .replace(/<\/(p|div|section|article|tr|ul|ol|table|blockquote|dd|dt|figure|figcaption|pre)>/gi, '\n\n');
const texte = decoder(sansBalise(h)).replace(/[ \t\u00A0]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/^#{1,6}\s*$/gm, '').trim();
return [{ json: { titre: titre, texte: texte, nb_caracteres: texte.length, nb_caches: nb_caches } }];

// Mesurer : rassembler ce qui a été lu, quelle que soit la voie, et refuser un document vide, un scan ou un texte démesuré.
const d = $('Numéroter la version').first().json, j = $input.first().json || {};
let pages = null, texte = '', titre = d.titre, lecture = 'texte';
if (d.voie === 'direct') texte = String(d.texte || '');
else if (d.voie === 'page' || d.voie === 'page_fichier') { texte = String(j.texte || ''); titre = j.titre || d.titre; lecture = 'page'; }
else if (d.voie === 'texte_fichier') texte = String(j.data || '');
else if (Array.isArray(j.text)) { pages = j.text.map(String); texte = pages.join('\n\n'); }
else texte = String(j.text || '');
// Caractères invisibles (largeur nulle, sens d'écriture forcé, « étiquettes » Unicode) : ils servent à cacher du texte. On les compte, puis on les retire.
const INVISIBLES = /[\u200B-\u200F\u202A-\u202E\u2060-\u2064\uFEFF]|\uDB40[\uDC00-\uDC7F]/g;
const nb_invisibles = (texte.match(INVISIBLES) || []).length;
const sansInvisible = t => t.replace(INVISIBLES, '').replace(/\u00AD/g, '');
texte = sansInvisible(texte); if (pages) pages = pages.map(sansInvisible);
const norme = texte.replace(/\s+/g, ' ').trim();
// Le titre d'un fichier : sa première ligne si elle a l'allure d'un titre, sinon le nom du fichier.
if (d.origine === 'fichier') { const l1 = (texte.split('\n').map(l => l.trim()).find(Boolean) || '').replace(/^#+\s*/, ''); if (l1.length >= 8 && l1.length <= 80 && /^[A-Z\u00C0-\u00DD]/.test(l1) && !/[.;:,!?]$/.test(l1) && /[a-z\u00E0-\u00FF]{3}/.test(l1)) titre = l1; }
const MAX = 400000;
let message = '';
if (norme.length < 200) message = d.voie.startsWith('pdf') ? 'Ce PDF ne contient pas de texte : c\'est sans doute un document scanné. La lecture des scans n\'est pas encore branchée.'
  : d.voie === 'page' ? 'Cette page ne livre pas son texte : elle se construit peut-être dans le navigateur, ou elle est protégée.'
  : 'Ce document est vide, ou trop court pour être utile.';
else if (norme.length > MAX) message = 'Document trop long pour cette démonstration : ' + norme.length + ' signes, la limite est de ' + MAX + '.';
return [{ json: { ok: !message, message: message, titre: titre, lecture: lecture, texte: texte, pages: pages, texte_normalise: norme, nb_caracteres: norme.length, nb_invisibles: nb_invisibles, nb_caches: Number(j.nb_caches) || 0 } }];

// Découper : un passage par article ou par section quand le document a une structure ; sinon par paragraphes, à taille bornée.
// Entrée : { titre, texte } ou { titre, pages: [texte, ...] }. Sortie : un item par passage { ordre, repere, page, contenu, a_vectoriser }.
// Règle : aucun mot du document ne se perd. Un titre devient le repère du passage, tout le reste reste dans son contenu.
const e = $input.first().json;
const CIBLE = 1200, MAX = 1800, MIN = 200, LIMITE = 400;
const pages = Array.isArray(e.pages) && e.pages.length ? e.pages.map(String) : [String(e.texte || '')];
const propre = s => s.replace(/\r\n?/g, '\n').replace(/[ \t\u00A0\u202F]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const lignes = [];
pages.forEach((p, i) => { propre(p).split('\n').forEach(l => lignes.push({ t: l.trim(), page: pages.length > 1 ? i + 1 : null })); lignes.push({ t: '', page: null }); });

// Un titre « fort » se reconnaît à son mot (Article 3, Section 2, # Titre). Un titre « faible » y ressemble seulement (ligne numérotée, ligne en capitales).
const FORT = /^(#{1,6}\s+\S|(article|art\.|section|chapitre|titre|annexe|partie)\s+([0-9]+|[ivxlc]+)\b)/i;
const NUMERO = /^\d{1,2}(\.\d{1,2}){0,3}[.)]?\s+\S/;
const genre = l => {
  if (!l || l.length > 110) return null;
  if (FORT.test(l)) return 'fort';
  if (NUMERO.test(l) && l.length <= 90 && !/[.;,:]$/.test(l)) return 'faible';
  if (l.length >= 4 && l.length <= 70 && l === l.toUpperCase() && /[A-ZÀ-Ý]{3}/.test(l) && !/[.;,:]$/.test(l)) return 'faible';
  return null;
};
// « Article 3, Dentaire. Les soins... » sur une seule ligne : le titre s'arrête au premier point.
const coupe = l => { if (l.length <= 110 || !FORT.test(l)) return null; const m = l.match(/^(.{6,100}?)\.\s+(\S.*)$/) || l.match(/^(.{6,100}?):\s+(\S.*)$/); return m ? [m[1].trim(), m[2]] : null; };
const PUCE = /^([-•*·\u2013\u2014]|\d{1,2}[.)]|[a-z][.)])\s+/;
function paragraphes(ls) {
  const out = []; let cur = '';
  for (const l of ls) {
    if (!l) { if (cur) { out.push(cur); cur = ''; } continue; }
    if (!cur) { cur = l; continue; }
    if (PUCE.test(l)) { out.push(cur); cur = l; continue; }
    cur = /[A-Za-zÀ-ÿ]-$/.test(cur) && /^[a-zà-ÿ]/.test(l) ? cur.slice(0, -1) + l : cur + ' ' + l;
  }
  if (cur) out.push(cur); return out;
}

const blocs = []; let bloc = null;
const ouvrir = (titre, type, page) => { bloc = { titre: titre, type: type, page: page, lignes: [] }; blocs.push(bloc); };
for (const l of lignes) {
  const c = coupe(l.t);
  if (c) { ouvrir(c[0], 'fort', l.page); bloc.lignes.push(c[1]); continue; }
  const g = genre(l.t);
  if (g) { ouvrir(l.t.replace(/^#{1,6}\s+/, ''), g, l.page); continue; }
  if (!bloc) { if (!l.t) continue; ouvrir(null, null, l.page); }
  bloc.lignes.push(l.t);
}
const garde = []; let contexte = null;
blocs.forEach((b, i) => {
  b.paras = paragraphes(b.lignes); const taille = b.paras.join(' ').length, prec = garde[garde.length - 1];
  if (b.type === 'faible' && taille < 40) {            // faux titre : une ligne de liste, un intertitre nu. Il redevient du texte.
    if (prec) prec.paras.push(b.titre, ...b.paras); else { b.paras.unshift(b.titre); b.titre = null; b.type = null; garde.push(b); }
    return;
  }
  if (b.type === 'fort' && taille === 0) {             // titre de chapitre sans texte : il sert de contexte aux sections qui suivent
    if (i === blocs.length - 1 && prec) prec.paras.push(b.titre); else contexte = b.titre;
    return;
  }
  b.contexte = b.type === 'fort' ? contexte : null; garde.push(b);
});

const phrases = s => s.match(/[^.!?…]+(?:[.!?…]+["»”)]*(?:\s+|$)|$)/g) || [s];
const morceler = (s, max) => { const out = []; let r = s; while (r.length > max) { let k = r.lastIndexOf(' ', max); if (k < max * .5) k = max; out.push(r.slice(0, k).trim()); r = r.slice(k).trim(); } if (r) out.push(r); return out; };
function tasser(paras) {                               // regroupe en morceaux proches de CIBLE, sans couper une phrase
  const unites = [];
  for (const p of paras) {
    if (p.length <= MAX) { unites.push({ t: p, sep: '\n' }); continue; }
    let debut = true; for (const ph of phrases(p)) for (const m of morceler(ph.trim(), MAX)) if (m) { unites.push({ t: m, sep: debut ? '\n' : ' ' }); debut = false; }
  }
  const out = []; let cur = '';
  for (const u of unites) { if (cur && cur.length + u.t.length + 1 > CIBLE) { out.push(cur); cur = ''; } cur = cur ? cur + u.sep + u.t : u.t; }
  if (cur) out.push(cur); return out;
}
const dernierePhrase = s => { const ph = phrases(s.replace(/\n/g, ' ')); const d = (ph[ph.length - 1] || '').trim(); return d.length <= 300 ? d : ''; };

const passages = [];
for (const b of garde) {
  if (!b.paras.length) continue;
  const total = b.paras.join('\n'), morceaux = total.length <= MAX ? [total] : tasser(b.paras);
  const repere = b.titre ? (b.contexte && b.contexte !== b.titre ? b.contexte + ' › ' + b.titre : b.titre) : null;
  // Un bloc coupé en plusieurs morceaux : chaque suite reprend la dernière phrase du morceau précédent, pour ne pas perdre le fil.
  morceaux.forEach((m, k) => passages.push({ repere: repere, page: b.page, suite: k > 0, contenu: k > 0 ? [dernierePhrase(morceaux[k - 1]), m].filter(Boolean).join(' ') : m }));
}
const fin = [];
for (const p of passages) {                           // un fragment minuscule sans titre rejoint son voisin
  const prec = fin[fin.length - 1];
  if (!p.repere && !p.suite && p.contenu.length < MIN && prec && prec.contenu.length + p.contenu.length < MAX) { prec.contenu += '\n' + p.contenu; continue; }
  fin.push(p);
}
if (fin.length > 1 && !fin[0].repere && fin[0].contenu.length < MIN) { fin[1].contenu = fin[0].contenu + '\n' + fin[1].contenu; fin[1].page = fin[0].page || fin[1].page; fin.shift(); }
if (!fin.length) throw new Error('Aucun texte lisible dans ce document.');
if (fin.length > LIMITE) throw new Error('Document trop long : ' + fin.length + ' passages, la limite est de ' + LIMITE + '.');
const titre = String(e.titre || '').trim();
return fin.map((p, i) => {
  const repere = p.repere || (p.page ? 'page ' + p.page : 'partie ' + (i + 1));
  return { json: { ordre: i + 1, repere: repere, page: p.page, contenu: p.contenu, a_vectoriser: [titre, repere].filter(Boolean).join(' · ') + '\n' + p.contenu } };
});

// Écarter les consignes cachées : un document peut contenir une phrase qui s'adresse à l'IA au lieu d'informer le lecteur
// (« ignore tes consignes », « tu es maintenant... »). Un tel passage est mis à l'écart : ni vectorisé, ni mis en service.
// Le référent le voit dans le portail et décide. Ce filtre repère les formes connues ; la vraie barrière reste, à la réponse,
// un modèle qui ne reçoit les passages que comme des données, et un code qui vérifie chaque citation.
const plat = s => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’`]/g, "'").replace(/\s+/g, ' ');
const REGLES = [
  ["ordre d'ignorer les consignes", /(ignore[zr]?|oublie[zr]?|ne tiens? pas compte|ne tenez pas compte|ne pas tenir compte|fai(s|tes) abstraction|contourne[zr]?|desactive[zr]?|outrepasse[zr]?)\s+(de\s+|des\s+|du\s+|d')?(toutes?\s+)?(les\s+|tes\s+|vos\s+|ces\s+|mes\s+)?(consignes|instructions|regles|directives)/],
  ["ordre d'ignorer les consignes", /(ignore|disregard|forget|override|bypass)\s+((all|any|the|your|my|previous|prior|above|earlier)\s+)*(instructions?|rules?|prompts?|guidelines?)/],
  ['changement de rôle', /\b(tu es|vous etes|you are|act as|agis comme|comporte[- ]toi comme)\s+(maintenant|desormais|now|dorenavant)\b/],
  ["vocabulaire de pilotage d'une IA", /\b(system prompt|prompt systeme|message systeme|developer mode|mode developpeur|jailbreak|prompt injection)\b/],
  ["message adressé à l'IA", /\b(instructions?|consignes?|notes?|messages?|avis)\s+(pour|destinee?s?\s+a|a l'attention de|a l'intention de)\s+(l'|la |le |un |une |toute? )?(ia|intelligence artificielle|assistant ia|assistant virtuel|modele de langage|chatbot|llm|agent conversationnel)\b/],
  ["message adressé à l'IA", /\b(assistant|chatbot|ia)\s*:\s*(tu dois|vous devez|reponds|repondez|dis|dites|ecris|affirme|indique|ne (dis|mentionne|cite|revele))/],
  ['ordre de cacher ses sources', /\bne\s+(revele|cite|mentionne|divulgue)[zr]?\s+(jamais|pas|surtout pas|en aucun cas)\s+(tes|vos|les|ces)\s+(sources|consignes|instructions|regles)/],
  ['balise de conversation', /(<\/?(system|instructions?|assistant|im_start|im_end)\b|\[\/?(inst|system)\]|###\s*(instruction|system))/]
];
return $input.all().map(i => {
  const p = i.json, t = plat((p.repere || '') + ' ' + p.contenu);
  let motif = null, extrait = '';
  for (const [nom, regle] of REGLES) { const m = t.match(regle); if (m) { motif = nom; const k = Math.max(0, m.index - 40); extrait = t.slice(k, m.index + m[0].length + 60).trim(); break; } }
  if (!motif && /(^|\n)\s*(system|assistant)\s*:/i.test(p.contenu)) { motif = 'balise de conversation'; extrait = p.contenu.slice(0, 120); }
  return { json: Object.assign({}, p, { ecarte: !!motif, motif: motif, extrait: extrait }) };
});

// Préparer la vectorisation : tous les passages sains du document partent en un seul appel. Les passages mis à l'écart ne partent pas.
const p = $input.all().map(i => i.json).filter(x => !x.ecarte);
if (!p.length) throw new Error('Tous les passages de ce document ont été mis à l\'écart : ils contiennent des consignes adressées à l\'IA.');
return [{ json: { nb: p.length, entrees: p.map(x => x.a_vectoriser) } }];

// Joindre chaque passage à son vecteur, prêt pour la table. Les passages entrent hors service : ils ne répondent pas encore.
const d = $('Numéroter la version').first().json, m = $('Calculer son empreinte').first().json;
const passages = $('Écarter les consignes cachées').all(0).map(i => i.json).filter(x => !x.ecarte);
const vecteurs = (($input.first().json || {}).data || []).slice().sort((a, b) => a.index - b.index).map(v => v.embedding);
if (vecteurs.length !== passages.length) throw new Error('La vectorisation a rendu ' + vecteurs.length + ' vecteurs pour ' + passages.length + ' passages.');
return passages.map((p, i) => ({ json: { doc_id: d.doc_id, cle: d.cle, titre: m.titre, version: d.version, ordre: p.ordre, repere: p.repere, page: p.page, contenu: p.contenu,
  vecteur: '[' + vecteurs[i].map(x => Number(x).toFixed(5)).join(',') + ']', en_service: false } }));

// Noter l'échec : une étape s'est arrêtée (page injoignable, fichier illisible, vectorisation refusée). On le dit clairement, rien ne reste à moitié rangé.
const j = $input.first().json || {}, err = j.error || {};
const detail = String((typeof err === 'string' ? err : err.message || err.description) || j.message || 'cause inconnue').slice(0, 300);
// Le message technique est traduit pour la personne qui dépose ; le détail brut reste dans le registre.
const t = detail.toLowerCase();
const clair = /enotfound|eai_again/.test(t) ? 'Ce site est introuvable : l\'adresse est fausse, ou le site est hors ligne.'
  : /timeout|etimedout|econnreset|socket hang up/.test(t) ? 'Le site n\'a pas répondu à temps. Réessayez plus tard.'
  : /\b(401|403)\b|forbidden|unauthorized/.test(t) && !/openai|api key/.test(t) ? 'Ce site refuse l\'accès à cette page.'
  : /\b404\b|not found/.test(t) ? 'Cette page n\'existe pas, ou plus.'
  : /\b429\b|rate limit|quota|insufficient/.test(t) ? 'Le service de vectorisation a refusé la demande : quota atteint ou trop de demandes à la fois.'
  : /api key|incorrect api|invalid_api_key/.test(t) ? 'Le service de vectorisation refuse la clé enregistrée dans n8n.'
  : /mis à l'écart/.test(detail) ? detail
  : /pdf|password|encrypt/.test(t) ? 'Ce PDF ne se laisse pas lire : il est peut-être protégé ou abîmé.'
  : 'Le dépôt s\'est arrêté en cours de route. Le détail est inscrit au registre.';
let d = {}; try { d = $('Numéroter la version').first().json; } catch (e) {}
return [{ json: { echec: true, doc_id: d.doc_id || null, cle: d.cle || '', titre: d.titre || '', origine: d.origine || '', source: d.source || '', version: d.version || 0, message: clair, detail: detail } }];

// Répondre au portail : une seule sortie, quelle que soit l'issue. Le portail y lit le statut, les étapes franchies et les passages.
const j = $input.first().json || {};
const lire = n => { try { return $(n).first().json; } catch (e) { return null; } };
// La sortie 0 est nommée exprès : sans cela, n8n peut lire la sortie d'erreur d'un nœud, qui est vide.
const tous = n => { try { return $(n).all(0).map(i => i.json); } catch (e) { return []; } };
const d = lire('Numéroter la version'), m = lire('Mesurer le texte');
if (j.echec) return [{ json: { statut: 'erreur', message: j.message, titre: j.titre } }];
if (j.ok === false && j.motif) return [{ json: { statut: 'refuse', message: j.motif } }];
if (j.ok === false) return [{ json: { statut: 'erreur', message: j.message, titre: m ? m.titre : '' } }];
if (!j.doc_id && j.empreinte) return [{ json: { statut: 'doublon', message: 'Ce document est déjà en service, à l\'identique. Rien à refaire.', titre: m.titre, version: d.ancien.version,
  etapes: [{ nom: 'Reçu', detail: 'déjà en service, identique' }] } }];
const lus = tous('Écarter les consignes cachées'), passages = lus.filter(p => !p.ecarte), ecartes = lus.filter(p => p.ecarte);
const alertes = [];
if (ecartes.length) alertes.push(ecartes.length + ' passage' + (ecartes.length > 1 ? 's mis' : ' mis') + ' à l\'écart : consigne adressée à l\'IA');
if (m.nb_invisibles) alertes.push(m.nb_invisibles + ' caractère' + (m.nb_invisibles > 1 ? 's invisibles retirés' : ' invisible retiré'));
if (m.nb_caches) alertes.push(m.nb_caches + ' élément' + (m.nb_caches > 1 ? 's cachés retirés' : ' caché retiré') + ' de la page');
return [{ json: { statut: 'en_service', doc_id: d.doc_id, cle: d.cle, titre: m.titre, version: d.version, remplace: d.ancien ? d.ancien.version : null, nb_passages: passages.length, nb_caracteres: m.nb_caracteres,
  alertes: alertes,
  etapes: [
    { nom: 'Reçu', detail: d.ancien ? 'nouvelle version, la ' + d.version : 'sans doublon' },
    { nom: 'Lu', detail: m.lecture === 'page' ? 'page capturée, menus retirés' : 'texte lu tel quel' },
    { nom: 'Découpé', detail: passages.length + ' passage' + (passages.length > 1 ? 's' : '') + (ecartes.length ? ', ' + ecartes.length + ' mis à l\'écart' : '') },
    { nom: 'Vectorisé', detail: passages.length + ' × 512 nombres' },
    { nom: 'Rangé', detail: 'version ' + d.version + ' en service' + (d.ancien ? ', version ' + d.ancien.version + ' retirée' : '') }
  ],
  passages: passages.map(p => ({ ordre: p.ordre, repere: p.repere, page: p.page, contenu: p.contenu })),
  ecartes: ecartes.map(p => ({ ordre: p.ordre, repere: p.repere, motif: p.motif, extrait: p.extrait })) } }];
